from _lib import *
u1=U("count","Countable and uncountable","B1",
 "Some nouns cannot be counted in English even if they can in Bangla: information, advice, news, furniture, equipment, feedback, luggage. No plural -s, no a/an.",
 "information, advice, news, feedback, luggage — এগুলো কখনো s নেয় না, a/an-ও নয়।",
 [("Uncountable","some information · a piece of advice · much feedback · little time"),("Countable","a suggestion · two tips · many complaints · few options")],
 [("No -s, no a/an, singular verb.","s, a/an নয়; verb একবচন।","The information is correct."),
  ("To count them: a piece of, an item of, a bit of.","গুনতে চাইলে a piece of।","Let me give you a piece of advice."),
  ("much / little with uncountable; many / few with countable.","much আর many এর পার্থক্য।","How much luggage? How many bags?"),
  ("News is singular.","news একবচন।","The news is good.")],
 ["information","advice","news","feedback","equipment","much","many"],
 [("Can you give me some informations?","Can you give me some information?","Information has no plural.","informations নেই।"),
  ("He gave me an advice.","He gave me some advice / a piece of advice.","Advice is uncountable.","an advice নয়।"),
  ("The news are bad.","The news is bad.","News takes a singular verb.","news is।")],
 [C("Email.","Thank you for your ___ on the draft.",["feedback","feedbacks","a feedback","many feedback"],"feedback","Uncountable."),
  C("Office.","We need new ___ for the lab.",["equipment","equipments","an equipment","many equipments"],"equipment","Uncountable."),
  T("Breaking news.","The news ___ spreading fast.","be",["is"],"News is singular."),
  F("Pick the correct sentence.",["She gave me many useful advices.","She gave me a lot of useful advice.","She gave me an useful advice.","She gave me many useful advice."],"She gave me a lot of useful advice.","Advice is uncountable; a lot of works for both."),
  C("Airport.","How ___ luggage do you have?",["much","many","few","a"],"much","Luggage is uncountable."),
  B("আমার কাছে খুব অল্প সময় আছে।",["I have very little time.","I have very few time.","I have very less times.","I have very little times."],"I have very little time.","Time (uncountable): little."),
  C("Fewer or less.","We received ___ complaints this month.",["fewer","less","little","much"],"fewer","Countable plural: fewer (less is common in speech, but fewer is correct).",True),
  C("Work.","I have a lot of ___ to do today.",["work","works","a work","many works"],"work","Work (job tasks) is uncountable.",True)])
u2=U("agree","Subject–verb agreement","B2",
 "The verb agrees with the real subject, not the nearest noun. Watch out for 'one of', 'each', 'everyone', long subjects and 'there is/are'.",
 "verb আসল subject-এর সাথে মিলবে, পাশের noun-এর সাথে নয়।",
 [("Singular","Everyone is · Each employee has · One of my friends lives"),("Plural","Both are · A number of people have · There are two issues")],
 [("One of + plural noun + singular verb.","one of the … is।","One of our clients is unhappy."),
  ("Everyone, everybody, each, every: singular.","সবাই = everyone is।","Everyone in the team knows."),
  ("Find the head noun in long subjects.","মূল noun খুঁজুন।","The list of new products is ready."),
  ("There is + singular, there are + plural.","there is/are পরের noun দেখে।","There are three emails waiting.")],
 ["one of","each","everyone","there is / are","a number of"],
 [("One of my colleague are sick.","One of my colleagues is sick.","Plural noun, singular verb.","one of এর পরে plural noun, verb একবচন।"),
  ("Everyone have a laptop.","Everyone has a laptop.","Everyone is singular.","everyone has।"),
  ("There is many problems.","There are many problems.","Plural noun: are.","there are।")],
 [C("Team talk.","Everyone in the team ___ the new policy.",["supports","support","are supporting","have supported"],"supports","Everyone: singular."),
  C("Complaint.","One of the printers ___ not working.",["is","are","were","have"],"is","One of ... is."),
  T("Report.","The quality of the products ___ improved.","have",["has"],"Head noun: quality (singular)."),
  F("Pick the correct sentence.",["There is two issues we need to fix.","There are two issues we need to fix.","There have two issues we need to fix.","It has two issues we need to fix."],"There are two issues we need to fix.","There are + plural."),
  C("Office.","Each of the managers ___ a parking space.",["has","have","are having","having"],"has","Each: singular."),
  B("আমার একজন বন্ধু কানাডায় থাকে।",["One of my friends lives in Canada.","One of my friend lives in Canada.","One of my friends live in Canada.","My one friend live in Canada."],"One of my friends lives in Canada.","One of + plural + singular verb."),
  C("Statistics.","A number of employees ___ asked for remote work.",["have","has","is","was"],"have","A number of = many: plural.",True),
  C("Statistics.","The number of employees ___ grown this year.",["has","have","are","were"],"has","The number (one figure): singular.",True)])
save("nouns","Nouns and agreement",
 "Informations, advices, 'one of my friend' — these small slips make English sound foreign. Master the noun rules and agreement once.",
 "ছোট ভুলগুলো ঠিক করলেই ইংরেজি পরিষ্কার শোনায়।",[u1,u2],
 [C("Email.","Please send me more ___ about the course.",["information","informations","an information","many informations"],"information","Uncountable."),
  C("Office.","Neither of the options ___ perfect.",["is","are","were being","have"],"is","Neither of: singular in formal English."),
  F("Pick the correct sentence.",["The furnitures in the office is new.","The furniture in the office is new.","The furniture in the office are new.","The furnitures in the office are new."],"The furniture in the office is new.","Uncountable, singular verb."),
  B("প্রত্যেক কর্মী একটা আইডি কার্ড পায়।",["Every employee gets an ID card.","Every employees get an ID card.","Every employee get a ID card.","All employee gets an ID card."],"Every employee gets an ID card.","Every + singular + singular verb; an ID (vowel sound)."),
  T("Report.","There ___ a lot of traffic this morning.","be (past)",["was"],"Traffic is uncountable: was."),
  C("Talk.","How ___ people attended?",["many","much","little","less"],"many","People: countable plural.")])
